from __future__ import annotations

import base64

from PySide6.QtGui import QPixmap

# Logo institucional proporcionado por el usuario para el encabezado de AIP.
# Se mantiene embebido para que el runtime no dependa de rutas externas.
_LOGO_PNG_BASE64 = """"""


def coopealianza_logo_pixmap() -> QPixmap:
    """Devuelve el logo institucional sin depender del sistema de archivos."""

    pixmap = QPixmap()
    pixmap.loadFromData(base64.b64decode(_LOGO_PNG_BASE64), "PNG")
    return pixmap
